// Function to return the greatest common divisor of a and b
public long gcd(long a, long b) {
    // Continue the loop until b becomes 0
    while (b != 0) {
        // Swap a with b and b with the remainder of a divided by b
        long temp = b;
        b = a % b;
        a = temp;
    }
    // The GCD is stored in a
    return a;
}

