class Solution {
    public int numIslands(char[][] grid) {
        // create the nodes for union find
        int m = grid.length, n = grid[0].length;
        Node[][] nodes = new Node[m][n];
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                nodes[i][j] = new Node();
            }
        }

        // connect nodes
        UnionFind uf = new UnionFind();
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (grid[i][j] == '0') continue;

                if (j &lt; n - 1 && grid[i][j + 1] == '1') {
                    uf.union(nodes[i][j], nodes[i][j + 1]);
                }

                if (i &lt; m - 1 && grid[i + 1][j] == '1') {
                    uf.union(nodes[i][j], nodes[i + 1][j]);
                }
            }
        }

        // count distinct root nodes as the number of islands
        Set&lt;Node&gt; set = new HashSet&lt;&gt;();
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (grid[i][j] == '1') {
                    set.add(uf.find(nodes[i][j]));
                }
            }
        }
        return set.size();
    }

