class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        Map&lt;Integer, Node&gt; map = new HashMap&lt;&gt;();
        UnionFind uf = new UnionFind();
        for (int i = 0; i &lt; n; i++) {
            int n1 = edges[i][0];
            int n2 = edges[i][1];
            if (!map.containsKey(n1)) map.put(n1, new Node());
            if (!map.containsKey(n2)) map.put(n2, new Node());

            if (!uf.union(map.get(n1), map.get(n2))) {
                return new int[]{n1, n2};
            }
        }
        return new int[]{};
    }

    public class Node {
        public Node parent;
        public int rank;

        public Node() {
            this.parent = this;
            this.rank = 0;
        }
    }

    public class UnionFind {
        public boolean union(Node x, Node y) {
            Node rx = find(x);
            Node ry = find(y);
            if (rx == ry) return false;

            if (rx.rank &gt; ry.rank) {
                ry.parent = rx;
            } else if (rx.rank &lt; ry.rank) {
                rx.parent = ry;
            } else {
                ry.parent = rx;
                rx.rank++;
            }
            return true;
        }

        public Node find(Node node) {
            while (node != node.parent) {
                node = node.parent;
            }
            return node;
        }
    }
}

Union Find
I wish I could say this for every leetcode problem, but it is straightforward once we recognize that union find is applicable to this problem. If we see every cell in the grid as a node in a graph, and an island is just a set of connected nodes. Identifying the island with the maximal area requires us to find the islands first, in other words, we need to connect the cells into islands first.
The idea here is use a Node class to represent a cell in the graph. A Node object keeps track of its parent node and how many nodes are connected in the current island.
class Solution {
    public int maxAreaOfIsland(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Node[][] nodes = new Node[m][n];
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                nodes[i][j] = new Node();
            }
        }

        int maxArea = 0;
        UnionFind uf = new UnionFind();
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (grid[i][j] == 0) continue;
                maxArea = Math.max(maxArea, nodes[i][j].size);

                if (j &lt; n - 1 && grid[i][j + 1] == 1) {
                    int size = uf.union(nodes[i][j], nodes[i][j + 1]);
                    maxArea = Math.max(maxArea, size);
                }

                if (i &lt; m - 1 && grid[i + 1][j] == 1) {
                    int size = uf.union(nodes[i][j], nodes[i + 1][j]);
                    maxArea = Math.max(maxArea, size);
                }
            }
        }
        return maxArea;
    }

    public class Node {
        public Node parent;
        public int rank;
        public int size;

        public Node() {
            this.parent = this;
            this.rank = 0;
            this.size = 1;
        }
    }

    public class UnionFind {
        public int union(Node x, Node y) {
            Node rx = find(x), ry = find(y);
            if (rx == ry) return rx.size;

            if (rx.rank &lt; ry.rank) {
                rx.parent = ry;
                ry.size += rx.size;
                return ry.size;
            } else if (rx.rank &gt; ry.rank) {
                ry.parent = rx;
                rx.size += ry.size;
                return rx.size;
            } else {
                rx.parent = ry;
                ry.rank++;
                ry.size += rx.size;
                return ry.size;
            }
        }

        public Node find(Node node) {
            Node temp = node;
            while (temp != temp.parent) {
                temp = temp.parent;
            }
            node.parent = temp;
            return node.parent;
        }
    }
